{
  "items": [
    {
      "text": "Bid compliance: assemble the proposal as a single PDF of at most 20 pages, and submit it through the College's procurement portal by 2026-12-01 12:00 UTC. Ensure the service goes live for students by 2027-01-11, the first day of spring enrollment.",
      "requirement_ids": [
        "REQ-0002",
        "REQ-0014"
      ],
      "basis": "The instructions fix the format, page limit, submission channel, deadline, and live date. Portal availability is an assumption."
    },
    {
      "text": "Audit and retention: maintain an audit record of every signature event, capturing the signer's identity, time, and document version, and store signed documents for ten years.",
      "requirement_ids": [
        "REQ-0003",
        "REQ-0007"
      ],
      "basis": "The required event details and the ten-year duration are explicitly stated. The storage medium is an assumption."
    },
    {
      "text": "Browser compatibility and reminders: support signing on current desktop and mobile browsers. Send a reminder to each signer who has not signed within 72 hours.",
      "requirement_ids": [
        "REQ-0004",
        "REQ-0005"
      ],
      "basis": "Desktop and mobile browsers and the 72-hour reminder window are specified. The reminder communication channel is an assumption."
    },
    {
      "text": "System integration and availability: integrate the service with the College's student records system via its existing REST API. Maintain a service availability of 99.5% in each calendar month, excluding planned maintenance announced five working days in advance.",
      "requirement_ids": [
        "REQ-0009",
        "REQ-0011"
      ],
      "basis": "The REST API integration and the 99.5% availability metric with maintenance exclusions are provided. Monitoring tools are assumed."
    }
  ],
  "unmapped_requirement_ids": [
    "REQ-0006",
    "REQ-0008",
    "REQ-0010",
    "REQ-0012"
  ],
  "open_questions": [
    {
      "text": "Should templates for the College's twelve most used forms be included, and what format are they provided in?",
      "requirement_ids": [
        "REQ-0006"
      ]
    },
    {
      "text": "What is the volume of signed records to be migrated by 2027-02-28, and what is the current tool's data structure?",
      "requirement_ids": [
        "REQ-0008"
      ]
    },
    {
      "text": "Should the optional on-premises deployment option be priced separately, and what infrastructure requirements apply?",
      "requirement_ids": [
        "REQ-0010"
      ]
    },
    {
      "text": "What specific communication channel should be used to respond to severity-one incidents within one hour?",
      "requirement_ids": [
        "REQ-0012"
      ]
    }
  ]
}
